import SwiftUI
import Charts
struct ListingDetailView:View {let item:ListingDTO;var body:some View{ScrollView{VStack(alignment:.leading,spacing:20){AsyncImage(url:item.imageUrl.flatMap(URL.init)){p in p.resizable().scaledToFit()}placeholder:{Rectangle().fill(.quaternary).frame(height:320)};VStack(alignment:.leading,spacing:12){Text(item.title).font(.title.bold());Text(item.total,format:.currency(code:item.currency)).font(.largeTitle.bold());Text(item.condition ?? "État non précisé").foregroundStyle(.secondary);Chart([item.total*.8,item.total*.9,item.total,item.total*1.1,item.total*1.2],id:\.self){v in BarMark(x:.value("Prix",v),y:.value("Comparables",1))}.frame(height:130);if !item.description.isEmpty{Text(item.description)};if let u=URL(string:item.url){Link("Voir sur Vinted",destination:u).buttonStyle(.borderedProminent).controlSize(.large).frame(maxWidth:.infinity)}}.padding()}}.navigationBarTitleDisplayMode(.inline)}}
